from typing import List

def draw_cardiogram(a: List[int]) -> None:
    n = len(a)
    total_sum = sum(a)
    max_height = max(abs(sum(a[:i+1])) for i in range(n))
    height_offset = max_height // 2

    for y in range(total_sum, -total_sum - 1, -1):
        line = [' ' * total_sum]
        current_y = height_offset
        for x, val in enumerate(a):
            if current_y == abs(y):
                line[-1] = line[-1][:x] + '/' + line[-1][x+1:]
            elif current_y > abs(y):
                line.append(' ' * (val - 1) + '\\')
            else:
                line.append(' ' * (val - 1) + '/')
            current_y += (-1) ** (x + 1) * val
        print(''.join(line))

