from io import StringIO

def draw_cardiogram(n, a):
    max_height = abs(sum(a))
    width = sum(a)
    output = [[' ' for _ in range(width)] for _ in range(max_height)]

    x, y = 0, 0
    for i in range(n):
        if i % 2 == 0:
            dx, dy = a[i], -a[i]
        else:
            dx, dy = -a[i], a[i]

        for j in range(abs(dx)):
            nx, ny = x + (dx // abs(dx)), y + (dy * j) // abs(dx)
            output[ny][nx] = '/' if dx > 0 else '\\'
            x, y = nx, ny

        if dx < 0:
            for j in range(abs(dy)):
                nx, ny = x + (dx // abs(dx)), y + (dy * j) // abs(dy)
                output[ny][nx] = '\\' if dy > 0 else '/'
                x, y = nx, ny

    for row in reversed(output):
        print(''.join(row))

