import sys

def draw_cardiogram(a):
    total_sum = sum(a)
    height = total_sum // 2
    width = total_sum

    # Create a grid filled with spaces
    grid = [[' ' for _ in range(width)] for _ in range(height)]

    x, y = 0, height
    for i in range(len(a)):
        if i % 2 == 0:
            for dx in range(a[i]):
                if x + dx < width and y - 1 >= 0:
                    grid[y - 1][x + dx] = '/'
                x += 1
        else:
            for dx in range(a[i]):
                if x + dx < width and y + 1 < height:
                    grid[y + 1][x + dx] = '\\'
                x += 1

    # Print the grid
    for row in grid:
        print(''.join(row))

